import { dirname, join, resolve } from "node:path";
import process from "node:process";

export const repoRoot = resolve(import.meta.dirname, "../..");
export const manifestPath = join(repoRoot, "src-tauri/Cargo.toml");
export const fixtures = join(repoRoot, "src-tauri/tests/fixtures");
export const resultsDir = join(repoRoot, "e2e-results");
/** Generated by global setup; see `inputs.ts`. */
export const inputsDir = join(resultsDir, "inputs");
/** Written by Khronos' `ktx create` in global setup; see `corpus.ts`. */
export const corpusDir = join(resultsDir, "corpus");

const exe = process.platform === "win32" ? ".exe" : "";

/** Set by global setup from cargo's build output (the target dir may be relocated). */
function driverPath(): string {
  const path = process.env.KTXFORGE_E2E_DRIVER;
  if (path === undefined || path === "") {
    throw new Error("KTXFORGE_E2E_DRIVER is not set; run the suite through `npm run e2e`");
  }
  return path;
}

/**
 * The official `ktx` that `tauri-build` copies next to the driver. Tests use it as the
 * independent oracle: what Khronos' own tool reads back from our output.
 */
export function ktxPath(): string {
  return join(dirname(driverPath()), `ktx${exe}`);
}

export function input(name: string): string {
  return join(inputsDir, name);
}

export function fixture(name: string): string {
  return join(fixtures, name);
}

export function corpus(name: string): string {
  return join(corpusDir, name);
}
